/**
 * @method
 * @name scwin.Chk_Digit_Plus
 * @author Inswave
 * @date 2026. 09. 29
 * @param str
 * @returns
 * @hidden N
*/
scwin.Chk_Digit_Plus = function (str) {
    /* sdd-asis-lifecycle:begin Chk_Digit_Plus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < str.length; i++) {
        const ch = str.charAt(i);
        if ((ch < "0" || ch > "9")) {
            return false;
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.beforIsur
 * @author Inswave
 * @date 2026. 09. 29
 * @param applId
 * @returns
 * @hidden N
*/
scwin.beforIsur = async function (applId) {
    /* sdd-asis-lifecycle:begin beforIsur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF10100 || { elements: [] });
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    if (isur_cd === '') {
        await $c.win.alert("발행기관 코드를 입력 하세요.");
        return;
    }
    const url = "/stdcd/bond.do?method=bfReturnReAppl";
    const params = "isur_cd=" + isur_cd + "&applId=" + applId + "&menuId=10100";
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("직전입력분 자료가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
