/**
 * @method
 * @name scwin.dateFormatValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dateFormatValidation = function () {
    /* sdd-asis-lifecycle:begin dateFormatValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.JLDINF10100 || { elements: [] });
    if ($c.date.dateCompare($c.util.getComponent('cal_isuDd'), "발행일")) {
        return true;
    }
    if ($c.date.dateCompare($c.util.getComponent('cal_redmptDd'), "상환일")) {
        return true;
    }
    if ($c.date.dateCompare($c.util.getComponent('cal_saleDd'), "선/후매출일")) {
        return true;
    }
    if ($c.date.dateCompare($c.util.getComponent('cal_fstIntPayDd'), "최초이자지급일")) {
        return true;
    }
    if ($c.date.dateCompare($c.util.getComponent('cal_grtYdStrtDd'), "보장수익률적용일")) {
        return true;
    }
    if ($c.date.dateCompare($c.util.getComponent('cal_addYdStrtDd'), "추가수익률적용일")) {
        return true;
    }
    if ($c.date.dateCompare(fm.int_rt_decsn_bas_dd, "최초표면이자율결정기준일")) {
        return true;
    }
    if ($c.date.dateCompare(fm.exer_strt_dd, "행사개시일")) {
        return true;
    }
    if ($c.date.dateCompare(fm.exer_end_dd, "행사종료일")) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


