/**
 * @method
 * @name scwin.setRedmptDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj addYy
 * @returns
 * @hidden N
*/
scwin.setRedmptDd = async function (obj, addYy) {
    /* sdd-asis-lifecycle:begin fn_setRedmptDd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const isuDd = obj.value;
    const frm = (document.JLDINF10100 || { elements: [] });
    const len = isuDd.length;
    if (isuDd == null || isuDd === "") {
        await $c.win.alert("발행일을 입력하세요.");
        $c.util.getComponent("cal_isuDd").focus();
        return;
    }
    const tmpYy = isuDd.substr(0, 4);
    const tmpMm = isuDd.substr(5, 2);
    const tmpDd = isuDd.substr(8, 2);
    const tmpMmDd = isuDd.substring(4, len);
    let redmptDd = parseInt(tmpYy) + parseInt(addYy);
    redmptDd += "-" + tmpMm + "-" + tmpDd;
    $c.util.getComponent("cal_redmptDd").setValue(redmptDd);
    $c.util.getComponent("cal_redmptDd").focus();
    /* sdd-asis-lifecycle:end */
};


