/**
 * @method
 * @name scwin.setCfiGroup
 * @author Inswave
 * @date 2026. 09. 29
 * @param div
 * @returns
 * @hidden N
*/
scwin.setCfiGroup = function (div) {
    /* sdd-asis-lifecycle:begin fn_SetCfiGroup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const bTmp = $c.util.getComponent('slc_bndTpCd').getValue();
    const sTmp = $c.util.getComponent('ipt_stkRelCorpbndRghtTpCd').getValue();
    const aTmp = $("td#asst_secutiz_tp_cd input:checked").val();
    if (div === "1") {
        if (bTmp === "GB") {
            $('input[name=group][value=B]').prop("checked", true);
            scwin.chg_group($("#group_B"));
        } else {
            if (bTmp === "MB") {
                $('input[name=group][value=N]').prop("checked", true);
                scwin.chg_group($("#group_N"));
            } else {
                $('input[name=group][value=B]').prop("checked", true);
                scwin.chg_group($("#group_B"));
            }
        }
    } else {
        if (div === "2") {
            if (sTmp === "10" || sTmp === "11" || sTmp === "32") {
                $('input[name=group][value=C]').prop("checked", true);
